<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/public/css/app.css"><title>Utilisateurs · <?= htmlspecialchars($application['name']) ?></title><body class="outdoor-mode"><?php require __DIR__ . '/../partials/header.php'; ?><main class="auth-page"><h1>Utilisateurs</h1><p><a href="/">Retour à l’application</a></p><table class="users-table"><thead><tr><th>Nom</th><th>E-mail</th><th>Rôle</th><th>Action</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><?= htmlspecialchars($user['first_name'] . ' ' . $user['last_name']) ?></td><td><?= htmlspecialchars($user['email']) ?></td><td><?= htmlspecialchars($user['role']) ?></td><td><?php if ($user['role'] === 'contributeur'): ?><form method="post" action="/admin/utilisateurs/promouvoir"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="user_id" value="<?= htmlspecialchars($user['id']) ?>"><button>Passer administrateur</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></main><?php require __DIR__ . '/../partials/footer.php'; ?></body></html>
